Link: http://patchwork.freedesktop.org/patch/msgid/1465487895-7401-1-git-send-email-cpaul@redhat.com

Here is the root cause:
The bug is caused by enabling Frame Buffer Compression (FBC) by default on Haswell systems, which leads to video artifacts during playback and kernel freezes in certain environments. This indicates that the FBC implementation may not be fully compatible or stable on Haswell hardware, particularly when running specific desktop environments like GNOME, Openbox, and others.

Here is the patch:

 static bool intel_fbc_can_choose(struct intel_crtc *crtc)
 {
 	struct drm_i915_private *dev_priv = crtc->base.dev->dev_private;
 	struct intel_fbc *fbc = &dev_priv->fbc;
-	bool enable_by_default = IS_HASWELL(dev_priv) ||
-				 IS_BROADWELL(dev_priv);
+	bool enable_by_default = IS_BROADWELL(dev_priv);

 	if (intel_vgpu_active(dev_priv)) {
 		fbc->no_fbc_reason = "VGPU is active";
 		return false;
 	}

 	if (i915.enable_fbc < 0 && !enable_by_default) {
 		fbc->no_fbc_reason = "disabled per chip default";
 		return false;
 	}

 	if (!i915.enable_fbc) {
 		fbc->no_fbc_reason = "disabled per module param";
 		return false;
 	}

 	if (fbc_on_pipe_a_only(dev_priv) && crtc->pipe != PIPE_A) {
 		fbc->no_fbc_reason = "no enabled pipes can have FBC";
 		return false;
 	}

 	if (fbc_on_plane_a_only(dev_priv) && crtc->plane != PLANE_A) {
 		fbc->no_fbc_reason = "no enabled planes can have FBC";
 		return false;
 	}

 	return true;
 }



